// GATE MEASUREMENT for shared-v1 T002 u4 (the Collapsible vertical).
//
// The T001 spec §1 puts the Collapsible S1 provider entry in `CollapsibleRoot.tsx`,
// which ALSO carries an M4 host row (it renders a `<div>`). Only an entry with
// "accepted S1 and NO M4 host row (MenuRoot)" prints a declaration-only module.
// So the Collapsible defining module is the DECLARATION-PLUS-HOST shape, and the
// consumers (`CollapsibleTrigger`, `CollapsiblePanel`) import the hook from it
// across a module boundary on the renamed spelling.
//
// u3 landed the cross-module route against a DECLARATION-ONLY defining module.
// This probe asks the one question u4 must answer before printing anything:
// does a defining module that ALSO has a component export the hook, so the
// cross-module consumer's import resolves?

import { buildEnrichedIr } from '@frameless/compiler';

/** The defining module in the Collapsible shape: a shared factory AND its own host component. */
export const HOST_DECLARATION = `import { shared, state } from "@markless/core";

export const usePanel = shared(() => {
	let open = state(false);
	return { open, toggle() { open = !open; } };
}, { scope: "container" });

export function PanelRoot() @{
	const panel = usePanelLocal();
	<div data-root>{panel.open ? "open" : "closed"}</div>
}
`;

/** Same, but the host reads the definition under its own declared name (no rename needed locally). */
export const HOST_DECLARATION_PLAIN = `import { shared, state } from "@markless/core";

export const usePanel = shared(() => {
	let open = state(false);
	return { open, toggle() { open = !open; } };
}, { scope: "container" });

export function PanelRoot() @{
	const panel = usePanel();
	<div data-root>{panel.open ? "open" : "closed"}</div>
}
`;

export const HOST_CONSUMER = `import { usePanel as usePanelShared } from "./lift-shared-host-decl.tsrx";

export function PanelTrigger() @{
	const panel = usePanelShared();
	<button data-trigger onClick={() => { panel.toggle(); }}>toggle</button>
}
`;

export const HOST_SPECIFIER = './lift-shared-host-decl.tsrx';
export const HOST_DECLARATION_FILENAME = 'lift/generated/probe/lift-shared-host-decl.tsrx';
export const HOST_CONSUMER_FILENAME = 'lift/generated/probe/lift-shared-host-consumer.tsrx';

export const HOST_MODULES: ReadonlyMap<string, { filename: string; source: string }> = new Map([
	[HOST_SPECIFIER, { filename: HOST_DECLARATION_FILENAME, source: HOST_DECLARATION_PLAIN }],
