	redeclarationEvidence,
	TIER_CONSUMER,
	TIER_CONSUMER_FILENAME,
	TIER_DECLARATION,
	TIER_DECLARATION_FILENAME,
	TIER_MODULES,
} from '../../react/test/lift-shared-scope-probe.ts';
import { emit } from '../src/emitter/index.ts';

// THE u3b EMIT CONTRACT, PINNED (shared-v1 / T002 u3b, Solid lane).
//
// The pair sources are SHARED with the React lane on purpose: the point of the
// contract is that one `.tsrx` pair produces the same JOIN in every lane that
// has a `shared` lowering, so measuring both lanes against different sources
// would measure two different things. They live in the React package because
// that is where u2 put the probe; nothing in them is React-specific.
//
// This lane has NO tier concept - it emits one uniform context + hook + provider
// shape - which is what makes it a useful second measurement of ruling 2. The
// tier still has to arrive on the spliced record and still has to be a valid
// one, because a table this lane hands on must be complete; it simply does not
// branch on it. So the SIGNATURE-AGREEMENT pin here is about arity zero on both
// sides, and it goes red the same way if a consumer starts inventing its own
// declaration.

const pairModules = async (): Promise<{ defining: string; consumer: string }> => ({
	defining: emit(
		await buildEnrichedIr({ filename: PAIR_DECLARATION_FILENAME, source: PAIR_DECLARATION }),
	),
	consumer: emit(
		await buildEnrichedIr({
			filename: PAIR_CONSUMER_FILENAME,
			source: PAIR_CONSUMER,
			importedModules: PAIR_MODULES,
		}),
	),
});

describe('Solid emit contract for a cross-module shared pair', () => {
	test('the defining module emits the hook and provider once, and exports both', async () => {
		const { defining } = await pairModules();
		expect(defining).toContain('export function usePanel(');
		expect(defining).toContain('export function PanelProvider(');
		expect(defining).toContain('createContext');
	});

	// THE NO-REDECLARATION PIN. Rejected-design mutation A - splicing the imported
	// record into `sharedDefinitions` with a marker - turns all three true.
	test('the consumer declares no context, no provider and no hook of its own', async () => {
		const { consumer } = await pairModules();
		expect(redeclarationEvidence(consumer, 'usePanelShared')).toEqual({
			context: false,
			provider: false,
			hook: false,
		});
	});

	test('the hook reaches the consumer as an import specifier and call sites only', async () => {
		const { consumer } = await pairModules();
		expect(consumer).toContain(
			"import { usePanel as usePanelShared } from './lift-shared-pair-decl.jsx';",
		);
		expect(callArities(consumer, 'usePanelShared')).toEqual([0]);
	});

