	test('the defining hook signature and every consumer call agree by value', async () => {
		const { defining, consumer } = await pairModules();
		const declared = declaredArity(defining, 'usePanel');
		expect(declared).toBe(0);
		for (const arity of callArities(consumer, 'usePanelShared')) expect(arity).toBe(declared);
	});

